describe('pdf page and zoom controls', () => {
  it('opens a document at its first page and its own size', () => {
    const pages = new UiPdfPages();
    pages.open(3);
    expect(pages.page()).toBe(1);
    expect(pages.count()).toBe(3);
    expect(pages.zoom()).toBe(1);
    expect(pages.hasPrevious()).toBe(false);
    expect(pages.hasNext()).toBe(true);
  });

  it('pages within the document', () => {
    const pages = new UiPdfPages();
    pages.open(2);
    pages.previous();
    expect(pages.page()).toBe(1);
    pages.next();
    pages.next();
    expect(pages.page()).toBe(2);
    expect(pages.hasNext()).toBe(false);
  });

  it('zooms within its steps', () => {
    const pages = new UiPdfPages();
    pages.open(1);
    for (let step = 0; step < PDF_ZOOM_STEPS.length; step += 1) {
      pages.zoomIn();
    }
    expect(pages.zoom()).toBe(PDF_ZOOM_STEPS[PDF_ZOOM_STEPS.length - 1]);
    expect(pages.canZoomIn()).toBe(false);
    for (let step = 0; step < PDF_ZOOM_STEPS.length; step += 1) {
      pages.zoomOut();
    }
    expect(pages.zoom()).toBe(PDF_ZOOM_STEPS[0]);
    expect(pages.canZoomOut()).toBe(false);
  });

  it('shows no page once its document is closed', () => {
    const pages = new UiPdfPages();
    pages.open(4);
    pages.next();
    pages.close();
    expect(pages.count()).toBe(0);
    expect(pages.page()).toBe(1);
  });
});
